#include "ksPanelControlTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
#include <utility>
int main(){using T=ks::PanelControlTask;using S=T::Stage;using R=T::Read;using W=T::Write;unsigned cases=0;auto verify=[&](unsigned mode,unsigned input,unsigned limit,unsigned old,unsigned mask,unsigned set,unsigned selector,unsigned offset){T t;unsigned offsetReads=0,ticks=0;uint8_t port=0;std::vector<std::pair<W,unsigned>>writes;auto clock=[](W w){return w==W::Mirror?3u:1u;};while(t.stage()!=S::Complete){auto stage=t.stage();if(stage==S::SetStrobe)port^=0x95;auto cost=t.nextClocks(clock);if(t.advanceBefore(cost-1,[](R){return 0;},[](W,uint8_t){},clock))throw std::runtime_error("early");t.advanceBefore(cost,[&](R r)->unsigned{switch(r){case R::Selector:return selector;case R::Offset:return offsetReads++?uint8_t(offset+7):offset;case R::Limit:return limit;case R::Mode:return mode;case R::Mirror:if(t.offset()!=offset)throw std::runtime_error("mirror binding");return old;case R::Input:return input;case R::Mask:return mask;case R::Set:return set;case R::Port:return port;}return 0;},[&](W w,uint8_t v){writes.emplace_back(w,v);if(w==W::Port||w==W::Strobe)port=v;},clock);if(stage==S::Tick)++ticks;}unsigned clamped=input<limit?input:limit;unsigned shifted=clamped>=1&&clamped<=127?(clamped>=8?0:uint8_t(set<<clamped)):set;unsigned output=mode==2?(old&0xf0)|input:mode==3?(old&15)|uint8_t(input<<4):(old&mask)|(mode==1?(input?set:0):shifted);unsigned selected=uint8_t(offset+7)|0x30,clear=selected&0xdf,last=(clear^0x95)|0x20;std::vector<std::pair<W,unsigned>>expected{{W::Mirror,output},{W::Data,output},{W::Port,selected},{W::Strobe,clear},{W::Strobe,last}};if(writes!=expected||t.output()!=output||ticks!=3||t.tableOffset()!=selector*5||offsetReads!=2)throw std::runtime_error("panel formula/order/late port/binding");++cases;};for(unsigned mode=0;mode<256;++mode)for(unsigned input=0;input<256;++input)verify(mode,input,127,input^0xaa,0x55,0xa5,mode,255-mode);for(unsigned limit=0;limit<256;++limit)for(unsigned input=0;input<256;++input)verify(0,input,limit,0x55,0x55,0xa5,input,limit);for(unsigned mode:{1u,2u,3u})for(unsigned old=0;old<256;++old)for(unsigned input=0;input<256;++input)verify(mode,input,255,old,0x55,0xa5,input,old);for(unsigned mode:{0u,1u})for(unsigned mask=0;mask<256;++mask)for(unsigned set=0;set<256;++set)verify(mode,1,1,0xaa,mask,set,mask,set);std::cout<<"PASS: "<<cases<<" pure panel-control properties\n";}
